// newAuthSetupCmd prints concrete steps for getting a credential. Side-effect
// rule: print by default, --launch opt-in to open the URL, short-circuit when
// the verifier is running this in a sandboxed subprocess.
func newAuthSetupCmd(_ *rootFlags) *cobra.Command {
	var launch bool
	cmd := &cobra.Command{
		Use:     "setup",
		Short:   "Print steps for obtaining a credential (use --launch to open the URL)",
		Example: "  granola-cli auth setup\n  granola-cli auth setup --launch",
		RunE: func(cmd *cobra.Command, args []string) error {
			w := cmd.OutOrStdout()
			fmt.Fprintln(w, "No setup URL is configured for this CLI; check the API's docs.")
			fmt.Fprintf(w, "  printf %%s \"$GRANOLA_API_KEY\" | granola-cli auth set-token\n")
			fmt.Fprintln(w, "  (the token is read from stdin or $GRANOLA_API_KEY, never from argv)")
			fmt.Fprintln(w, "")
			fmt.Fprintln(w, "Optional request credentials:")
			fmt.Fprintln(w, "  export GRANOLA_API_KEY=\"your-token-here\"")
			if !launch {
				return nil
			}
			fmt.Fprintln(cmd.ErrOrStderr(), "no setup URL configured; cannot launch")
			return nil
		},
	}
	cmd.Flags().BoolVar(&launch, "launch", false, "Open the setup URL in your default browser")
	return cmd
}

func newAuthStatusCmd(flags *rootFlags) *cobra.Command {
	return &cobra.Command{
		Use:     "status",
		Short:   "Show authentication status",
		Example: "  granola-cli auth status",
		RunE: func(cmd *cobra.Command, args []string) error {
			cfg, err := config.Load(flags.configPath)
			if err != nil {
				return configErr(err)
			}

			w := cmd.OutOrStdout()
			header := cfg.AuthHeader()
			authed := header != ""
			// JSON envelope: {authenticated, verified, source, config}. When not
			// authenticated, write the envelope first then return authErr
			// so exit code carries the auth-failure signal.
			if flags.asJSON {
				out := map[string]any{
					"authenticated": authed,
					"verified":      false,
					"source":        cfg.AuthSource,
					"config":        cfg.Path,
				}
				if printErr := printJSONFiltered(w, out, flags); printErr != nil {
					return printErr
				}
				if !authed {
					return authErr(fmt.Errorf("no credentials configured"))
				}
				return nil
			}
			if !authed {
				fmt.Fprintln(w, red("Not authenticated"))
				fmt.Fprintln(w, "")
				fmt.Fprintln(w, "Set your token (read from stdin or $GRANOLA_API_KEY, never from argv):")
				fmt.Fprintf(w, "  printf %%s \"$GRANOLA_API_KEY\" | granola-cli auth set-token\n")
				fmt.Fprintln(w, "")
				fmt.Fprintln(w, "Optional request credentials:")
				fmt.Fprintln(w, "  export GRANOLA_API_KEY=\"your-token-here\" # Granola public API key (bearer) for the public REST API at public-api.granola.ai. Human notes are read through the official Granola MCP.")
				return authErr(fmt.Errorf("no credentials configured"))
			}

			fmt.Fprintln(w, green("Credentials present (not verified)"))
			fmt.Fprintf(w, "  Source: %s\n", cfg.AuthSource)
			fmt.Fprintf(w, "  Config: %s\n", cfg.Path)
			return nil
		},
	}
}

func newAuthSetTokenCmd(flags *rootFlags) *cobra.Command {
	return &cobra.Command{
		Use:   "set-token",
		Short: "Save an API token to the credentials file (reads the token from stdin or $GRANOLA_API_KEY)",
		Long: `Save an API token to the credentials file.

The token is NEVER passed as a command-line argument — argv is visible to
other processes (ps, /proc) and lands in shell history. Provide it one of two
secure ways:

  printf %s "$TOKEN" | granola-cli auth set-token
  GRANOLA_API_KEY="$TOKEN" granola-cli auth set-token`,
		Example: strings.Trim(`
  printf %s "$TOKEN" | granola-cli auth set-token
  GRANOLA_API_KEY="$TOKEN" granola-cli auth set-token`, "\n"),
		Args: cobra.ArbitraryArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) > 0 {
				return usageErr(fmt.Errorf("set-token does not accept the token as an argument (argv is visible to other processes and shell history); pipe it on stdin: printf %%s \"$TOKEN\" | granola-cli auth set-token, or set GRANOLA_API_KEY"))
			}
			token, err := readSetTokenValue(cmd)
			if err != nil {
				return err
			}

			cfg, err := config.Load(flags.configPath)
			if err != nil {
				return configErr(err)
			}

			// Clear any legacy auth_header so AuthHeader() falls through to
			// the newly-saved credential. Without this, a pre-existing
			// auth_header value (common after regenerate) shadows the saved
			// token and set-token silently has no effect. Silent clear (no
			// log line): a masked-tail variant could leak token bytes through
			// scripted dogfood that captures stderr.
			cfg.AuthHeaderVal = ""
			if err := cfg.SaveTokens("", "", token, "", cfg.TokenExpiry); err != nil {
				return configErr(fmt.Errorf("saving token: %w", err))
			}

			savePath := credentialSavePath(cfg)
			// JSON envelope: {saved, config_path, credentials_path}.
			if flags.asJSON {
				out := map[string]any{
					"saved":       true,
					"config_path": cfg.Path,
				}
				if !cfg.AgentcookieManagedByExternalStore() {
					out["credentials_path"] = savePath
				}
				return printJSONFiltered(cmd.OutOrStdout(), out, flags)
			}
			fmt.Fprintf(cmd.OutOrStdout(), "Token saved to %s\n", savePath)
			return nil
		},
	}
}

// maxTokenBytes bounds the stdin read so a wedged or hostile stdin cannot
// exhaust memory; an API token is a few KB at most.
const maxTokenBytes = 64 << 10

// readSetTokenValue resolves the token for `auth set-token` without ever
// touching argv. Piped/redirected stdin wins (the documented
// `printf %s "$TOKEN" | ... set-token` path); otherwise it falls back to the
// GRANOLA_API_KEY env var. Whitespace is trimmed. An empty result returns a
// usage error with the secure invocation guidance.
func readSetTokenValue(cmd *cobra.Command) (string, error) {
	if stdinHasData(cmd) {
		// Read one byte past the cap: if the extra byte materializes the input
		// is over the limit and is REJECTED, never silently truncated — a
		// truncated secret would be saved as a corrupt, unusable token.
		data, err := io.ReadAll(io.LimitReader(cmd.InOrStdin(), maxTokenBytes+1))
		if err != nil {
			return "", ioErr(fmt.Errorf("reading token from stdin: %w", err))
		}
		if len(data) > maxTokenBytes {
			return "", usageErr(fmt.Errorf("token on stdin exceeds %d bytes; refusing to truncate a secret", maxTokenBytes))
		}
		if token := strings.TrimSpace(string(data)); token != "" {
			return token, nil
		}
	}
	if v := strings.TrimSpace(os.Getenv("GRANOLA_API_KEY")); v != "" {
		return v, nil
	}
	return "", usageErr(fmt.Errorf("no token provided; pipe it on stdin (printf %%s \"$TOKEN\" | granola-cli auth set-token) or set GRANOLA_API_KEY"))
}

// stdinHasData reports whether a token can be read from the command's stdin.
// For the real process stdin it is true only when stdin is piped or
// redirected (not an interactive terminal); when a test injects a reader via
// cmd.SetIn it is always true.
func stdinHasData(cmd *cobra.Command) bool {
	in := cmd.InOrStdin()
	if in == os.Stdin {
		fi, err := os.Stdin.Stat()
		if err != nil {
			return false
		}
		return (fi.Mode() & os.ModeCharDevice) == 0
	}
	return in != nil
}

func credentialSavePath(cfg *config.Config) string {
	if cfg != nil && cfg.AgentcookieManagedByExternalStore() {
		return cfg.Path
	}
	if path, err := cliutil.CredentialsFilePath(); err == nil {
		return path
	}
	if cfg != nil {
		return cfg.Path
	}
	return ""
}

func newAuthLogoutCmd(flags *rootFlags) *cobra.Command {
	return &cobra.Command{
		Use:     "logout",
		Short:   "Clear stored credentials",
		Example: "  granola-cli auth logout",
		RunE: func(cmd *cobra.Command, args []string) error {
			cfg, err := config.Load(flags.configPath)
			if err != nil {
				return configErr(err)
			}

			if err := cfg.ClearTokens(); err != nil {
				return configErr(fmt.Errorf("clearing tokens: %w", err))
			}

			// Identify which (if any) auth env var is still exported so the
			// JSON envelope and the human prose can both surface it.
			envStillSet := ""
			if envStillSet == "" && os.Getenv("GRANOLA_API_KEY") != "" {
				envStillSet = "GRANOLA_API_KEY"
			}

			// JSON envelope: {cleared: true, note?: "<env_var> env var is still set"}.
			if flags.asJSON {
				out := map[string]any{"cleared": true}
				if envStillSet != "" {
					out["note"] = envStillSet + " env var is still set"
				}
				return printJSONFiltered(cmd.OutOrStdout(), out, flags)
			}

			if envStillSet != "" {
				fmt.Fprintf(cmd.OutOrStdout(), "Config cleared. Note: %s env var is still set.\n", envStillSet)
				return nil
			}
			fmt.Fprintln(cmd.OutOrStdout(), "Logged out. Credentials cleared.")
			return nil
		},
	}
}

// openSetupURL opens url in the OS default browser with a literal per-OS
// command and the URL as a single argv element - no shell, nothing
// caller-controlled in the command position. It is the same browser-open the
// press emits for OAuth connectors; `mcp-auth login` uses it to start the
// authorization-code + PKCE flow against Granola's official MCP server.
func openSetupURL(url string) error {
	var c *exec.Cmd
	switch runtime.GOOS {
	case "darwin":
		c = exec.Command("open", url)
	case "linux":
		c = exec.Command("xdg-open", url)
	case "windows":
		c = exec.Command("rundll32", "url.dll,FileProtocolHandler", url)
	default:
		return fmt.Errorf("unsupported OS: %s", runtime.GOOS)
	}
	return c.Start()
}
